-- Move isolated application schema. No modifications to energy/public.
create schema if not exists move;
revoke all on schema move from public, anon, authenticated;
create table if not exists move.organizations(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Europe/Stockholm',created_at timestamptz not null default now());
create table if not exists move.memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references move.organizations(id),user_id uuid not null references auth.users(id),full_name text not null,role text not null check(role in ('owner','admin','manager','employee')),employment_type text not null default 'hourly' check(employment_type in ('hourly','permanent')),unique(organization_id,user_id),unique(id,organization_id));
create table if not exists move.jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references move.organizations(id),title text not null,customer_name text,origin_address text,destination_address text,scheduled_start timestamptz not null,scheduled_end timestamptz not null,notes text,status text not null default 'draft' check(status in ('draft','published','cancelled','completed')),check(scheduled_end>scheduled_start),unique(id,organization_id));
create table if not exists move.shifts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references move.organizations(id),starts_at timestamptz not null,ends_at timestamptz not null,notes text,check(ends_at>starts_at),unique(id,organization_id));
create table if not exists move.shift_offers(id uuid primary key default gen_random_uuid(),organization_id uuid not null,shift_id uuid not null,employee_id uuid not null,status text not null default 'offered' check(status in ('offered','accepted','declined','withdrawn')),responded_at timestamptz,unique(shift_id,employee_id),foreign key(shift_id,organization_id) references move.shifts(id,organization_id),foreign key(employee_id,organization_id) references move.memberships(id,organization_id));
create table if not exists move.job_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_id uuid not null,employee_id uuid not null,unique(job_id,employee_id),foreign key(job_id,organization_id) references move.jobs(id,organization_id),foreign key(employee_id,organization_id) references move.memberships(id,organization_id));
create table if not exists move.employee_availability(id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,day date not null,status text not null check(status in ('available','unavailable')),unique(employee_id,day),foreign key(employee_id,organization_id) references move.memberships(id,organization_id));
create table if not exists move.time_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,job_id uuid,work_type text not null default 'job' check(work_type in ('job','travel','warehouse','other')),starts_at timestamptz not null,ends_at timestamptz not null,unpaid_break_minutes integer not null default 0 check(unpaid_break_minutes>=0),comment text,status text not null default 'submitted' check(status in ('draft','submitted','approved','rejected')),approved_by uuid,approved_at timestamptz,check(ends_at>starts_at),check(extract(epoch from (ends_at-starts_at))/60>unpaid_break_minutes),check((work_type='job')=(job_id is not null)),foreign key(employee_id,organization_id) references move.memberships(id,organization_id),foreign key(job_id,organization_id) references move.jobs(id,organization_id));
create table if not exists move.materials(id uuid primary key default gen_random_uuid(),organization_id uuid not null references move.organizations(id),name text not null,unit text not null default 'st',active boolean not null default true,unique(id,organization_id),unique(organization_id,name));
create table if not exists move.job_material_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_id uuid not null,material_id uuid not null,reported_by uuid not null,quantity numeric(12,2) not null check(quantity>0),created_at timestamptz not null default now(),foreign key(job_id,organization_id) references move.jobs(id,organization_id),foreign key(material_id,organization_id) references move.materials(id,organization_id),foreign key(reported_by,organization_id) references move.memberships(id,organization_id));
create index if not exists move_jobs_org_start on move.jobs(organization_id,scheduled_start);
create index if not exists move_time_employee_start on move.time_entries(employee_id,starts_at);
create index if not exists move_material_job on move.job_material_entries(job_id);
do $$ declare t text; begin foreach t in array array['organizations','memberships','jobs','shifts','shift_offers','job_assignments','employee_availability','time_entries','materials','job_material_entries'] loop execute format('alter table move.%I enable row level security',t); end loop; end $$;
